"""Private Alertmanager0.28 HTTP/gossip peers on loopback; no external destinations."""
import os,json,pathlib,shutil,subprocess,socket,tempfile,time,urllib.request,urllib.error,contextlib
import yaml


def free_port():
    for _ in range(100):
        with socket.socket() as tcp:
            tcp.bind(('127.0.0.1',0));port=tcp.getsockname()[1]
            try:
                with socket.socket(socket.AF_INET,socket.SOCK_DGRAM) as udp:udp.bind(('127.0.0.1',port))
                return port
            except OSError:pass
    raise RuntimeError('NATIVE_ENVIRONMENT_ERROR: private ports unavailable')


class Alertmanager:
    def __init__(self,config=None,mesh=False,peers=(),advertise=None,cluster_options=()):
        self.config=config or {'route':{'receiver':'sink','group_wait':'1h'},'receivers':[{'name':'sink'}]}
        self.port=free_port();self.cluster_port=free_port() if mesh else None;self.peers=peers;self.advertise=advertise;self.cluster_options=tuple(cluster_options)
        self.base='http://127.0.0.1:'+str(self.port);self.proc=None
    def __enter__(self):
        self.temp=tempfile.TemporaryDirectory(prefix='of-am-');self.root=pathlib.Path(self.temp.name);self.log=(self.root/'server.log').open('wb')
        try:
            version=subprocess.check_output(['alertmanager','--version'],stderr=subprocess.STDOUT,text=True,timeout=3)
            if '0.28.' not in version:raise RuntimeError('NATIVE_ENVIRONMENT_ERROR: Alertmanager0.28 required')
            path=self.root/'config.yaml';path.write_text(yaml.safe_dump(self.config,sort_keys=False),encoding='utf8')
            args=['alertmanager','--config.file='+str(path),'--storage.path='+str(self.root/'state'),'--web.listen-address=127.0.0.1:'+str(self.port),'--log.level=error']
            args+=['--cluster.listen-address=' if self.cluster_port is None else '--cluster.listen-address=127.0.0.1:'+str(self.cluster_port)]
            if self.cluster_port is not None:
                args+=['--cluster.advertise-address=127.0.0.1:'+str(self.advertise or self.cluster_port),'--cluster.settle-timeout=100ms']
                args+=['--cluster.peer='+peer for peer in self.peers]
                args+=list(self.cluster_options)
            self.proc=subprocess.Popen(args,cwd=self.root,stdout=self.log,stderr=self.log,env={**os.environ,'GOMAXPROCS':'2','GOMEMLIMIT':'64MiB'})
            self.wait(lambda:self.request('/-/ready') is not None,'HTTP readiness')
            print('NATIVE_ALERTMANAGER_READY:0.28',flush=True);return self
        except BaseException:self.__exit__(None,None,None);raise
    def request(self,path,data=None,method=None):
        request=urllib.request.Request(self.base+path,data=None if data is None else json.dumps(data).encode(),headers={'Content-Type':'application/json'},method=method)
        opener=urllib.request.build_opener(urllib.request.ProxyHandler({}))
        with opener.open(request,timeout=1) as response:
            raw=response.read()
            return json.loads(raw) if raw and 'json' in response.headers.get('Content-Type','') else raw
    def wait(self,predicate,description,seconds=6):
        deadline=time.monotonic()+seconds
        while time.monotonic()<deadline:
            if self.proc.poll() is not None:raise RuntimeError('NATIVE_ENVIRONMENT_ERROR: private Alertmanager exited: '+(self.root/'server.log').read_text(errors='replace')[-2000:])
            try:
                value=predicate()
                if value:return value
            except (OSError,urllib.error.URLError):pass
            time.sleep(.03)
        raise AssertionError('native Alertmanager deadline: '+description)
    def __exit__(self,*args):
        if self.proc is not None:
            if self.proc.poll() is None:self.proc.terminate()
            try:self.proc.wait(timeout=3)
            except subprocess.TimeoutExpired:self.proc.kill();self.proc.wait(timeout=2)
        if getattr(self,'log',None):self.log.close()
        self.temp.cleanup()


def members(document):
    cluster=document['cluster'];names={cluster.get('name','')}
    names.update(peer.get('name','') for peer in cluster.get('peers',[]));names.discard('');return names


@contextlib.contextmanager
def pair():
    with Alertmanager(mesh=True) as first,Alertmanager(mesh=True,peers=['127.0.0.1:'+str(first.cluster_port)]) as second:
        first.wait(lambda:len(members(first.request('/api/v2/status')))>=2,'first gossip peer list')
        second.wait(lambda:len(members(second.request('/api/v2/status')))>=2,'second gossip peer list')
        print('NATIVE_ALERTMANAGER_GOSSIP_READY:2-members',flush=True);yield first,second

