"""Owned Alertmanager restart changes only retention, retaining private storage and notification policy."""
import os,subprocess
from alertmanager_native import Alertmanager
class RetainedAlertmanager(Alertmanager):
 def __init__(self,config,retention):super().__init__(config);self.retention=retention
 def __enter__(self):
  super().__enter__()
  try:self.restart(self.retention);return self
  except BaseException:self.__exit__(None,None,None);raise
 def restart(self,seconds):
  if type(seconds) is not int or not 1<=seconds<=30:raise ValueError('bounded teaching retention')
  if self.proc.poll() is None:self.proc.terminate();self.proc.wait(timeout=3)
  args=['alertmanager','--config.file='+str(self.root/'config.yaml'),'--storage.path='+str(self.root/'state'),'--web.listen-address=127.0.0.1:'+str(self.port),'--cluster.listen-address=','--data.retention='+str(seconds)+'s','--data.maintenance-interval=100ms','--log.level=error']
  self.proc=subprocess.Popen(args,cwd=self.root,stdout=self.log,stderr=self.log,env={**os.environ,'GOMAXPROCS':'2','GOMEMLIMIT':'64MiB'})
  self.wait(lambda:self.request('/-/ready') is not None,'retained storage restart');self.retention=seconds
